import Dashboard from './Dashboard';

// Good example: parallel data fetching
async function getParallelData() {
  try {
    const [users, posts, stats] = await Promise.all([
      fetch('https://api.example.com/users').then(r => r.json()),
      fetch('https://api.example.com/posts').then(r => r.json()),
      fetch('https://api.example.com/stats').then(r => r.json())
    ]);

    return { users, posts, stats };
  } catch {
    // Return mock data for build time
    return {
      users: [{ id: 1, name: 'User 1' }],
      posts: [{ id: 1, title: 'Post 1' }],
      stats: { views: 1000 }
    };
  }
}

export default async function Page() {
  const { users, posts, stats } = await getParallelData();

  return (
    <div>
      <h1>Dashboard</h1>
      <p>Users: {users.length}</p>
      <p>Posts: {posts.length}</p>
      <p>Total views: {stats.views}</p>

      <Dashboard />
    </div>
  );
}

import { headers } from 'next/headers';

type AnalyticsData = Record<string, unknown>;
type SettingsData = Record<string, unknown>;
type NotificationItem = Record<string, unknown> | string;

const fallbackData = {
  analytics: { visitors: 0, conversions: 0, revenue: 0 },
  notifications: [{ id: 1, message: 'No new notifications.' }],
  settings: { theme: 'system', emailNotifications: true }
};

// Good example: parallel data fetching with graceful fallback
async function getDashboardData() {
  try {
    const headerList = headers();
    const host = headerList.get('host');
    const protocol = headerList.get('x-forwarded-proto') ?? 'http';
    const baseUrl = host ? `${protocol}://${host}` : 'http://localhost:3000';

    const [analytics, notifications, settings] = await Promise.all([
      fetch(`${baseUrl}/api/analytics`).then(r => r.json()),
      fetch(`${baseUrl}/api/notifications`).then(r => r.json()),
      fetch(`${baseUrl}/api/settings`).then(r => r.json())
    ]);

    return {
      analytics: analytics as AnalyticsData,
      notifications: (notifications as NotificationItem[]) ?? [],
      settings: settings as SettingsData
    };
  } catch {
    // Return mock data for build time
    return fallbackData;
  }
}

function renderJson(data: unknown) {
  return <pre>{JSON.stringify(data, null, 2)}</pre>;
}

export default async function Dashboard() {
  const { analytics, notifications, settings } = await getDashboardData();

  return (
    <div>
      <h2>Dashboard Content</h2>

      <section>
        <h3>Analytics</h3>
        {renderJson(analytics)}
      </section>

      <section>
        <h3>Notifications</h3>
        <p>Total: {Array.isArray(notifications) ? notifications.length : 0}</p>
        {Array.isArray(notifications) ? (
          <ul>
            {notifications.map((notification, index) => {
              let key = `notification-${index}`;
              if (
                typeof notification === 'object' &&
                notification !== null &&
                'id' in notification
              ) {
                const value = (notification as { id?: string | number }).id;
                if (value !== undefined) key = String(value);
              }

              return (
                <li key={key}>
                  {typeof notification === 'string'
                    ? notification
                    : JSON.stringify(notification)}
                </li>
              );
            })}
          </ul>
        ) : (
          renderJson(notifications)
        )}
      </section>

      <section>
        <h3>Settings</h3>
        {renderJson(settings)}
      </section>
    </div>
  );
}
